import unittest
from unittest.mock import patch, MagicMock

class TestVirtualClinic(unittest.TestCase):

    @patch('virtual_clinic.system.get_speciality_wise_consultations')
    def test_speciality_wise_consultations(self, mock_get_consultations):
        mock_get_consultations.return_value = {'Speciality1': 10, 'Speciality2': 20}
        result = virtual_clinic.system.get_speciality_wise_consultations('Month')
        self.assertEqual(result, {'Speciality1': 10, 'Speciality2': 20})

    @patch('virtual_clinic.system.get_speciality_wise_revenue')
    def test_speciality_wise_revenue(self, mock_get_revenue):
        mock_get_revenue.return_value = {'Speciality1': 1000, 'Speciality2': 2000}
        result = virtual_clinic.system.get_speciality_wise_revenue('Quarter')
        self.assertEqual(result, {'Speciality1': 1000, 'Speciality2': 2000})

    @patch('virtual_clinic.system.get_patient_history')
    def test_patient_history(self, mock_get_history):
        mock_get_history.return_value = {'PatientId': '123', 'History': 'as specified'}
        result = virtual_clinic.system.get_patient_history('123')
        self.assertEqual(result, {'PatientId': '123', 'History': 'as specified'})

    @patch('virtual_clinic.system.create_consultation_request')
    def test_create_consultation_request(self, mock_create_request):
        mock_create_request.return_value = True
        result = virtual_clinic.system.create_consultation_request('Symptoms', 'Offline', '123')
        self.assertTrue(result)

    @patch('virtual_clinic.system.create_appointment_file')
    def test_create_appointment_file(self, mock_create_file):
        mock_create_file.return_value = True
        result = virtual_clinic.system.create_appointment_file('123')
        self.assertTrue(result)

    @patch('virtual_clinic.system.predict_diseases')
    def test_predict_diseases(self, mock_predict_diseases):
        mock_predict_diseases.return_value = {'Request1': 'Critical', 'Request2': 'Medium'}
        result = virtual_clinic.system.predict_diseases()
        self.assertEqual(result, {'Request1': 'Critical', 'Request2': 'Medium'})

    @patch('virtual_clinic.system.provide_diagnosis')
    def test_provide_diagnosis(self, mock_provide_diagnosis):
        mock_provide_diagnosis.return_value = True
        result = virtual_clinic.system.provide_diagnosis('Request1', 'Diagnosis', 'Medicine', 'LabRequest')
        self.assertTrue(result)

    @patch('virtual_clinic.system.update_prescription_status')
    def test_update_prescription_status(self, mock_update_status):
        mock_update_status.return_value = True
        result = virtual_clinic.system.update_prescription_status('PrescriptionId', 'Status')
        self.assertTrue(result)

if __name__ == '__main__':
    unittest.main()
